using Greyhaven.Content;
using Greyhaven.Server;
using System.Text.Json;
using System.Security.Cryptography;
using System.Text;
using var p=new ContentPackage(Path.GetFullPath(args[0]),Path.Combine(Path.GetFullPath(args[0]),"content/original/maps/reach-fixture.json"));var world=new OriginalWorld(p);var baseline=Wire.Encode(world.State);int count=0;
void Assert(bool ok,string why="Assertion failed"){if(!ok)throw new Exception(why);}
void Test(string name,Action test){world.Restore(new(){Campaign="slot1",Fingerprint=p.Fingerprint,MapHash=p.MapHash,Map=p.Map,State=JsonSerializer.Deserialize<SessionState>(baseline,ContentPackage.Json)!});world.State.Paused=false;test();count++;Console.WriteLine("PASS "+name);}
WorldItem Item(string suffix)=>world.State.Items.First(i=>i.Definition.EndsWith(suffix));
Reply Do(Command c)=>world.Handle(c);
void Accepted(Command c){var r=Do(c);Assert(r.Ok,r.Message);}
void Rejected(Command c){string before=Wire.Encode(world.State);var r=Do(c);Assert(!r.Ok,"Unexpected success");Assert(Wire.Encode(world.State)==before,"Rejected transaction changed state");}
void Invalid(Action<SessionState> change){var s=JsonSerializer.Deserialize<SessionState>(baseline,ContentPackage.Json)!;change(s);try{InventoryRules.Validate(p,s);}catch(ContentException){return;}throw new Exception("Expected invalid inventory");}
Test("initial inventory quantities, containers and merchant stock validate",()=>{InventoryRules.Validate(p,world.State);Assert(Item("silver-marks").Amount==125&&Item("healing-tonic").Amount==8&&world.State.MerchantStock.Count==10);});
Test("whole-stack ground and bag transfers preserve identity and quantity",()=>{var id=Item("healing-tonic").Id;Accepted(new(){Type="transfer",ItemId=id,Destination="ground",X=16,Y=20});Accepted(new(){Type="transfer",ItemId=id,Destination="bag",X=90,Y=160});Assert(InventoryRules.Find(world.State,id)!.Amount==8);});
Test("partial stack splits preserve sum and create a new identity",()=>{var i=Item("healing-tonic");Accepted(new(){Type="transfer",ItemId=i.Id,Destination="bag",X=150,Y=190,Amount=3});var stacks=world.State.Items.Where(x=>x.Definition==i.Definition).ToList();Assert(stacks.Count==2&&stacks.Sum(x=>x.Amount)==8&&InventoryRules.Find(world.State,i.Id)!.Amount==5);});
Test("stack merge removes source identity and remaps its quickbar",()=>{var i=Item("healing-tonic");Accepted(new(){Type="transfer",ItemId=i.Id,Destination="bag",Amount=3});var split=world.State.Items.Last();Accepted(new(){Type="bind",Slot=0,ItemId=split.Id});Accepted(new(){Type="transfer",ItemId=split.Id,Destination="stack",TargetId=i.Id});Assert(Item("healing-tonic").Amount==8&&world.State.Quickbar[0]=="item:"+i.Id&&InventoryRules.Find(world.State,split.Id)==null);});
Test("invalid amounts and incompatible merges roll back",()=>{foreach(int n in new[]{-1,9,int.MaxValue})Rejected(new(){Type="transfer",ItemId=Item("healing-tonic").Id,Destination="bag",Amount=n});Rejected(new(){Type="transfer",ItemId=Item("healing-tonic").Id,Destination="stack",TargetId=Item("silver-marks").Id});});
Test("container owns nested contents through ground and bag moves",()=>{var bag=Item("field-satchel").Id;var potion=Item("healing-tonic").Id;Accepted(new(){Type="transfer",ItemId=potion,Destination="container",TargetId=bag,X=70,Y=150});Accepted(new(){Type="transfer",ItemId=bag,Destination="ground",X=16,Y=20});Assert(!InventoryRules.Carried(world.State,InventoryRules.Find(world.State,potion)!));Accepted(new(){Type="transfer",ItemId=bag,Destination="bag",X=70,Y=150});Assert(InventoryRules.Carried(world.State,InventoryRules.Find(world.State,potion)!));});
Test("self and ancestor container loops are rejected atomically",()=>{var bag=Item("field-satchel").Id;var chest=Item("sea-chest").Id;Rejected(new(){Type="transfer",ItemId=bag,Destination="container",TargetId=bag});Accepted(new(){Type="transfer",ItemId=bag,Destination="container",TargetId=chest,X=70,Y=150});Rejected(new(){Type="transfer",ItemId=chest,Destination="container",TargetId=bag});});
Test("container weight limits include descendant stacks",()=>{var i=Item("healing-tonic");i.Amount=21;Rejected(new(){Type="transfer",ItemId=i.Id,Destination="container",TargetId=Item("field-satchel").Id});});
Test("nested ground contents cannot be accessed outside reach",()=>{var bag=Item("field-satchel").Id;var potion=Item("healing-tonic").Id;Accepted(new(){Type="transfer",ItemId=potion,Destination="container",TargetId=bag});Accepted(new(){Type="transfer",ItemId=bag,Destination="ground",X=18,Y=19});world.State.X=14;Rejected(new(){Type="transfer",ItemId=potion,Destination="bag"});Rejected(new(){Type="bind",ItemId=potion,Slot=0});});
Test("carrying weight counts contents exactly once",()=>{var before=InventoryRules.CarriedWeight(p,world.State);Accepted(new(){Type="transfer",ItemId=Item("healing-tonic").Id,Destination="container",TargetId=Item("field-satchel").Id});Assert(InventoryRules.CarriedWeight(p,world.State)==before);});
Test("overweight pickup rolls back all item and position changes",()=>{var chest=Item("sea-chest");world.State.Items.Add(new(){Id="heavy",Definition=Item("healing-tonic").Definition,Amount=95,Where="ground",X=16,Y=20});Rejected(new(){Type="transfer",ItemId="heavy",Destination="bag"});});
Test("explicit equipment slots reject wrong gear and non-equipment",()=>{Rejected(new(){Type="transfer",ItemId=Item("iron-sword").Id,Destination="equipped",TargetId="hat"});Rejected(new(){Type="transfer",ItemId=Item("healing-tonic").Id,Destination="equipped"});});
Test("equipping replacement stows previous hat without duplication",()=>{Accepted(new(){Type="transfer",ItemId=Item("wizard-hat").Id,Destination="equipped",TargetId="hat"});Assert(Item("trail-hat").Where=="bag"&&Item("wizard-hat").Where=="equipped");});
Test("two-handed weapon stows shield and reverse equip stows weapon",()=>{world.State.Items.Add(new(){Id="greatblade",Definition="greyhaven.item.mariner-greatblade",X=100,Y=150});Accepted(new(){Type="transfer",ItemId="greatblade",Destination="equipped"});Assert(Item("round-shield").Where=="bag"&&Item("iron-sword").Where=="bag");Accepted(new(){Type="transfer",ItemId=Item("round-shield").Id,Destination="equipped"});Assert(InventoryRules.Find(world.State,"greatblade")!.Where=="bag");});
Test("quickbar validates slots, ownership and spell identifiers",()=>{Accepted(new(){Type="bind",Slot=0,ItemId=Item("healing-tonic").Id});Accepted(new(){Type="bind",Slot=1,TargetId=p.Definitions.Spells[0].Id});Rejected(new(){Type="bind",Slot=10});Rejected(new(){Type="bind",Slot=0,TargetId="unknown"});Rejected(new(){Type="bind",Slot=2,ItemId=Item("sea-chest").Id});Accepted(new(){Type="bind",Slot=0});Assert(world.State.Quickbar[0]=="");});
Test("merchant buys and sells exact server-owned price and quantities",()=>{int before=InventoryRules.Marks(world.State);Accepted(new(){Type="trade",Destination="buy",TargetId=Item("healing-tonic").Definition,Amount=2});Assert(InventoryRules.Marks(world.State)==before-16);var bought=world.State.Items.Last();Accepted(new(){Type="trade",Destination="sell",ItemId=bought.Id,Amount=2});Assert(InventoryRules.Marks(world.State)==before-8&&InventoryRules.Find(world.State,bought.Id)==null);});
Test("insufficient funds and stock do not mutate currency or stock",()=>{Rejected(new(){Type="trade",Destination="buy",TargetId=Item("healing-tonic").Definition,Amount=21});Rejected(new(){Type="trade",Destination="buy",TargetId=Item("tide-crystal").Definition,Amount=20});});
Test("trade revision prevents duplicate or stale confirmation",()=>{int revision=world.State.Revision;Accepted(new(){Type="trade",Destination="buy",TargetId=Item("healing-tonic").Definition,Amount=1,ExpectedRevision=revision});Rejected(new(){Type="trade",Destination="buy",TargetId=Item("healing-tonic").Definition,Amount=1,ExpectedRevision=revision});});
Test("merchant rejects distant, equipped or filled-container sales",()=>{Rejected(new(){Type="trade",Destination="sell",ItemId=Item("iron-sword").Id,Amount=1});Accepted(new(){Type="transfer",ItemId=Item("healing-tonic").Id,Destination="container",TargetId=Item("field-satchel").Id});Rejected(new(){Type="trade",Destination="sell",ItemId=Item("field-satchel").Id,Amount=1});world.State.X=21;Rejected(new(){Type="trade",Destination="buy",TargetId=Item("tide-crystal").Definition,Amount=1});});
Test("journal records bounded notes and inventory activity",()=>{Accepted(new(){Type="note",Text="Remember the sea chest."});Assert(world.State.Journal.Last().Note);for(int i=0;i<210;i++)Accepted(new(){Type="note",Text="Entry "+i});Assert(world.State.Journal.Count==200&&world.State.Journal.Last().Text=="Entry 209");});
Test("pause blocks all inventory, trade and note mutations",()=>{world.State.Paused=true;foreach(var c in new[]{new Command{Type="note",Text="no"},new Command{Type="trade",Destination="buy",TargetId=Item("healing-tonic").Definition,Amount=1},new Command{Type="outfit"},new Command{Type="transfer",ItemId=Item("healing-tonic").Id,Destination="bag"}})Rejected(c);});
Test("save validator rejects malformed graph, amount and journal",()=>{Invalid(s=>s.Items[0].Amount=0);Invalid(s=>s.Items[0].ParentId="ghost");Invalid(s=>s.Items[0].Amount=2);Invalid(s=>s.Quickbar.Clear());Invalid(s=>s.Journal.Add(new(){Text=new string('x',241)}));});
Test("save roundtrip restores graph, quickbar, notes and stock",()=>{Accepted(new(){Type="transfer",ItemId=Item("healing-tonic").Id,Destination="container",TargetId=Item("field-satchel").Id});Accepted(new(){Type="bind",Slot=3,ItemId=Item("healing-tonic").Id});Accepted(new(){Type="note",Text="Persistent inventory."});string temp=Path.Combine(Path.GetTempPath(),"greyhaven-inventory-"+Guid.NewGuid());try{var store=new CampaignStore(temp,"slot1");store.Write(p,world.State,"manual");string expected=Wire.Encode(world.State);world.Restore(store.Read("manual"));world.State.Paused=false;Assert(Wire.Encode(world.State)==expected);}finally{Directory.Delete(temp,true);}});
Test("full container slot limit rejects split without removing units",()=>{var parent=Item("field-satchel").Id;for(int n=0;n<12;n++)world.State.Items.Add(new(){Id="slot."+n,Definition=Item("sealed-scroll").Definition,Where="container",ParentId=parent,X=70,Y=150});InventoryRules.Validate(p,world.State);Rejected(new(){Type="transfer",ItemId=Item("healing-tonic").Id,Destination="container",TargetId=parent,Amount=1});});
Test("maximum stack overflow rejects merge without losing either stack",()=>{world.State.Items.Add(new(){Id="large",Definition=InventoryRules.Currency,Amount=9998,Where="ground",X=16,Y=20});world.State.Items.Add(new(){Id="small",Definition=InventoryRules.Currency,Amount=2,Where="ground",X=16,Y=20});Rejected(new(){Type="transfer",ItemId="small",Destination="stack",TargetId="large"});});
Test("deep nesting fails before recursive weight traversal",()=>{Invalid(s=>{string parent=Item("field-satchel").Id;for(int n=0;n<9;n++){var id="deep."+n;s.Items.Add(new(){Id=id,Definition="greyhaven.item.field-satchel",Where="container",ParentId=parent,X=70,Y=150});parent=id;}});});
Test("overweight merchant purchase rolls back payment and stock",()=>{Item("healing-tonic").Amount=80;InventoryRules.Validate(p,world.State);Rejected(new(){Type="trade",Destination="buy",TargetId=Item("healing-tonic").Definition,Amount=10});});
Console.WriteLine(count+" inventory transaction checks passed.");
